head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > headerMerge]<br/>Header Column 의 ID 두 개를 사용하여 Header Column 을 직사각형 병합합니다.",
    "validation" : [
        "디자인 시 Header 를 병합하였거나 병합된 영역이 포함된 경우 메소드가 실행되지 않습니다.",
        "병합 성공 여부를 true/false 로 반환하며, 디자인 시 Header 를 병합한 경우나 병합된 영역이 포함된 경우 false 를 반환하고 병합이 실행되지 않습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 생성 (가장 먼저)
    $c.gcm.createLabel('label="디자인(정적) 으로 병합된 헤더입니다. 디자인 병합이 있으면 headerMerge 는 false 를 반환하고 미실행합니다."', '', 'label1');

    // 기존 dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    // grp_comp 영역 / 네임스페이스 확인
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // DataList 생성 (col1~col4) 후 데이터 4행 setJSON 으로 채우고 gridView 에 바인딩
    let strData = '';
    strData += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strData += '<w2:columnInfo>';
    for (let c = 1; c <= 4; c++) {
        strData += '<w2:column id="col' + c + '" name="name' + c + '" dataType="text"></w2:column>';
    }
    strData += '</w2:columnInfo>';
    strData += '<w2:data use="true"></w2:data>';
    strData += '</w2:dataList>';
    $p.data.create(strData);

    let jsonData = [];
    for (let rIdx = 1; rIdx <= 4; rIdx++) {
        jsonData.push({ col1: "v" + rIdx + "_1", col2: "v" + rIdx + "_2", col3: "v" + rIdx + "_3", col4: "v" + rIdx + "_4" });
    }
    dlt_bind.setJSON(jsonData);

    // 디자인(정적) 병합 헤더 그리드 생성
    //  - 다단(2-Row) 헤더 + 상위 '그룹' 헤더가 column2~column3 을 colSpan='2' 로 묶는 정적 병합 구조
    //  - column1 / column4 는 rowSpan='2' 로 두 Row 에 걸쳐 정적 병합
    //  → _hasMergedHeader() 가 true (_isStaticMerged) → headerMerge 가 false 반환 + 미실행
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:520px;height:260px;">';
    strTarget += '<w2:header style="" id="header1">';
    // Header Row1 : column1(rowSpan2) + 그룹헤더(colSpan2) + column4(rowSpan2)
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column rowSpan="2" width="120" inputType="text" id="column1" value="항목1"></w2:column>';
    strTarget += '<w2:column colSpan="2" width="240" inputType="text" id="hcol_group" value="그룹"></w2:column>';
    strTarget += '<w2:column rowSpan="2" width="120" inputType="text" id="column4" value="항목4"></w2:column>';
    strTarget += '</w2:row>';
    // Header Row2 : 그룹 하위 column2, column3
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="120" inputType="text" id="column2" value="항목2"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="column3" value="항목3"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    // Body : column1~column4 (단일 Row)
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="120" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 특정 Header th 의 colSpan / rowSpan 반환 (디자인 병합 유지/미실행 확인용)
scwin.getHeaderSpan = function (headerID) {
    let th = document.querySelector("th[data-header_id='" + headerID + "'], th[header_id='" + headerID + "']");
    if (!th) return "없음";
    let cs = th.getAttribute("colspan") || "1";
    let rs = th.getAttribute("rowspan") || "1";
    return "colspan=" + cs + ", rowspan=" + rs;
}



// (validation #1, #2) headerMerge 실행 — 디자인(정적) 병합이 있으므로 false 반환 + 미실행
scwin.btn_headerMerge_onclick = function () {
    let start = par_startHeaderID.getValue();
    let end = par_endHeaderID.getValue();

    // 실행 전 디자인 병합 상태(그룹 헤더 colspan, 항목1 rowspan)
    let beforeGroup = scwin.getHeaderSpan("hcol_group");
    let beforeCol1 = scwin.getHeaderSpan("column1");

    let result = target1.headerMerge(start, end);

    // 실행 후 디자인 병합 상태 — 미실행이므로 동일하게 유지되어야 함
    let afterGroup = scwin.getHeaderSpan("hcol_group");
    let afterCol1 = scwin.getHeaderSpan("column1");

    wf_body_bottom.getObj("scwin").setReturnValue(
        "headerMerge('" + start + "', '" + end + "') 반환값 : " + result
        + " → 디자인 병합 유지(미실행) : 그룹헤더 [" + beforeGroup + "] → [" + afterGroup + "]"
        + ", 항목1 [" + beforeCol1 + "] → [" + afterCol1 + "]"
    );
}
